\documentclass[border = 5mm]{standalone}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{patterns, intersections, arrows.meta, decorations.markings}

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

% Domain
\def\istart{-2}
\def\iend{2}

% Curve params	
\def\a{-1} % extr. 1
\def\b{2} % extr 2
\def\c{0.2} % stretch/squeeze along y 
\def\d{2} % t-shift

\begin{document}
\pagestyle{empty} %% IMPORTANT
\begin{tikzpicture}[
	declare function={ f(\x)=\c*\x*(6*\a*\b - 3*\a*\x - 3*\b*\x + 2*(\x)^2) + \d; } 
]


	\begin{axis}[
	tick label style={font=\footnotesize},
	label style={font=\small},
	tick style={draw=black,thick},
	axis line style = thick,
	axis y line = middle,
	axis x line = middle,
	%axis equal,
	xmin = -3.5,
	xmax = 3.5,
	ymin = -4.5,
	ymax = 4.5,
	xtick = {0},
	ytick = {0},
	%x tick label style={xshift={(\tick==-3)*-8pt}},
	xlabel = {$x$}, ylabel = {$y$},
	xlabel style={below right}, ylabel style={above left},
	every axis x label/.style={at={(ticklabel* cs:1.02)},anchor=west,},
	every axis y label/.style={at={(ticklabel* cs:1.02)}, anchor=south,}
	]

\draw[very thick, color=deepskyblue]
	plot[domain={\istart}:{\iend}, samples=200] (axis cs:{\x},{f(\x)});

% Points.
\node[circle, inner sep=1.5pt, draw=none, fill=orangepeel, label={above: \small $(-1,4)$}] 
	at (axis cs:{-1},{f(-1)}) {};
\node[circle, inner sep=1.5pt, draw=none, fill=orangepeel, label={right: \small $(2,-3)$}] 
	at (axis cs:{2},{f(2)}) {};
\node[circle, inner sep=1.5pt, draw=none, fill=orangepeel, label={left: \small }] 
	at (axis cs:{-2},{f(-2)}) {};

\node[] at (axis cs:1.3,1.7) {$y=f(x)$};

\end{axis}
\end{tikzpicture}
\end{document}
